_cache = None


def cargar():
    """(continentes, colores, fotogramas): continentes [(x, y, z)], colores [(r, g, b)] de los puntos
    de color y, por fotograma, (viento [(x, y, z)], puntos de color [(x, y, z)]). Coordenadas -1..1."""
    global _cache
    if _cache is None:
        d = zlib.decompress(base64.b64decode(DATOS))
        n_cont, n_fot, n_viento, n_col = struct.unpack_from("<HHHH", d, 0)
        pos = 8

        def puntos(n):
            nonlocal pos
            out = [tuple(v / 125 for v in struct.unpack_from("<3b", d, pos + 3 * i)) for i in range(n)]
            pos += 3 * n
            return out
        continentes = puntos(n_cont)
        colores = [tuple(c / 255 for c in d[pos + 3 * i:pos + 3 * i + 3]) for i in range(n_col)]
        pos += 3 * n_col
        fotogramas = []
        for _f in range(n_fot):
            viento = puntos(n_viento)
            fotogramas.append((viento, puntos(n_col)))
        _cache = (continentes, colores, fotogramas)
    return _cache
